import logging
import os.path
import distutils.dir_util
import distutils.file_util
import yaml
try:
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen

from .templates import SingleTemplate, Wrappable

log = logging.getLogger(__name__)


class TemplateSerializer(object):
    """ Read heat template file (usually stored with .yaml or .env extension). """
    def __init__(self, template_cls=SingleTemplate):
        self.__template_cls = template_cls

    def load(self, path):
        """Load heat template file, if chosen template class is Wrappable,
        then it will drop unrevelant information.

            :path: absolute file path
            :returns: SingleTemplate instance

        """

        is_local_file = not path.startswith("http://") and not path.startswith("https://")
        if is_local_file:
            with open(path, "r") as f:
                cfg = yaml.load(f)
        else:
            response = urlopen(path)
            cfg = yaml.load(response.read())
            response.close()

        heat_templ = self.__template_cls(cfg)
        if isinstance(heat_templ, Wrappable):
            heat_templ.wrap()
        return heat_templ

    def save(self, destination, template):
        """ Save `template` to `destination` directory. If `template` is
        Wrappable then it will restore information dropped during load.

            :destination: path to directory (str), directory has to exist
            :template: instance of SingleTemplate
        """
        if isinstance(template, Wrappable):
            template.unwrap()
        with open(destination, 'w') as file:
            content = yaml.dump(template.data, default_flow_style=False)
            file.write(content)


class FilesOperations(object):
    @staticmethod
    def copy_files(file_paths, destination_dir):
        """ Copy all files (`file_paths`) to `destination_dir`.

            :file_paths: list of relative/absolute paths to files, which
                             shall be copied
            :destination_dir: absolute/relative destination path (str),
                              directory should exist
        """
        new_paths = []
        for t_path in file_paths:
            basename = os.path.basename(t_path)
            log.debug('Copying {}...'.format(t_path))
            distutils.file_util.copy(t_path, destination_dir)
            new_path = os.path.join(destination_dir, basename)
            log.debug('File copied to {}'.format(new_path))
            new_paths.append(new_path)
        return new_paths

    @staticmethod
    def copy_dir_content(source_dir, destination):
        distutils.dir_util.copy_tree(source_dir, destination)
